  method: 'POST',
  body: params // Not supported
});
*/

// Workaround required:
impit.fetch('https://example.com/submit', {
  method: 'POST',
  // Manually set Content-Type (though impit *might* not need it if headers are auto-generated)
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params.toString() // Manual serialization required
});
```

